Use a circular buffer with 17 slots, a head index, and a count. The invariant is that count stays between 0 and 17, head identifies the next element to pop, and the next push goes to (head + count) modulo 17. A push on a full queue or a pop on an empty queue returns false without changing the queue; successful operations preserve FIFO order.

This complete C++17 implementation stores integers. The test checks filling, overflow rejection, draining, empty rejection, and wraparound while elements remain queued. Its checks remain enabled even when compiled with NDEBUG.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) {
            return false;
        }
        const std::size_t tail = (head_ + count_) % capacity;
        data_[tail] = value;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

void check(bool condition, const char* message) {
    if (!condition) {
        throw std::runtime_error(message);
    }
}

int main() {
    try {
        BoundedFIFO queue;
        int value = -1;

        // Fill all 17 slots.
        for (int i = 0; i < 17; ++i) {
            check(queue.push(i), "Initial push failed");
        }
        check(queue.full(), "Queue should be full");
        check(!queue.push(999), "Overflow must be rejected");
        check(queue.size() == 17, "Overflow changed size");

        // Drain and verify that overflow did not alter FIFO contents.
        for (int i = 0; i < 17; ++i) {
            check(queue.pop(value), "Initial pop failed");
            check(value == i, "Initial FIFO order incorrect");
        }
        check(queue.empty(), "Queue should be empty");
        value = -1;
        check(!queue.pop(value), "Empty pop must be rejected");
        check(value == -1, "Empty pop changed output");

        // Leave head at index 10 with seven elements still queued.
        for (int i = 0; i < 17; ++i) {
            check(queue.push(i), "Wraparound setup push failed");
        }
        for (int i = 0; i < 10; ++i) {
            check(queue.pop(value), "Wraparound setup pop failed");
            check(value == i, "Setup FIFO order incorrect");
        }

        // Reuse indices 0 through 9; the occupied range wraps.
        for (int i = 17; i < 27; ++i) {
            check(queue.push(i), "Wrapped push failed");
        }
        check(queue.full(), "Wrapped queue should be full");
        check(!queue.push(999), "Wrapped overflow must be rejected");

        // Pop across index 16 back to index 0.
        for (int i = 10; i < 27; ++i) {
            check(queue.pop(value), "Wrapped pop failed");
            check(value == i, "Wrapped FIFO order incorrect");
        }
        check(queue.empty(), "Final queue should be empty");
        check(!queue.pop(value), "Final empty pop must be rejected");

        std::cout << "All FIFO tests passed\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "Test failed: " << error.what() << '\n';
        return 1;
    }
}
```

Save as `fifo.cpp`, then compile and run:

```sh
g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo
./fifo
```

Push and pop each take constant time, and storage is fixed. This implementation is for single-threaded use; concurrent access requires synchronization.
